MODULE_SOURCES = json.loads("{\"sweep_competition_scope\":\"\\\"\\\"\\\"Cheap, deterministic scope gate BEFORE fixture-level sweep research.\\n\\nThis is NOT a C/C2 model, a confirmed-data source, or a prediction. It\\nprevents unlisted weak-data domestic competitions from entering the expensive\\nleague-channel verification loop. Source-visible raw fixture IDs stay in the\\naudit ledger. Required/protected/women's coverage is separately accounted.\\n\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport re\\nfrom typing import Any\\n\\n# Mirror the explicit league environment registry, not a global 'top flight'\\n# heuristic. Aliases need explicit review before promotion.\\nPRIORITY_NORMAL = frozenset({\\n    \\\"eredivisie\\\", \\\"netherlands eredivisie\\\", \\\"bundesliga\\\",\\n    \\\"german bundesliga\\\", \\\"belgian pro league\\\", \\\"belgian first division a\\\",\\n    \\\"eliteserien\\\", \\\"norwegian eliteserien\\\", \\\"allsvenskan\\\",\\n    \\\"sweden allsvenskan\\\", \\\"danish superliga\\\", \\\"superliga denmark\\\",\\n    \\\"besta deild karla\\\", \\\"iceland premier league\\\", \\\"austrian bundesliga\\\",\\n    \\\"mls\\\", \\\"major league soccer\\\", \\\"a-league men\\\", \\\"australia a-league men\\\",\\n    \\\"eerstedivisie\\\", \\\"eerste divisie\\\", \\\"netherlands eerste divisie\\\",\\n    \\\"premier league\\\", \\\"english premier league\\\", \\\"la liga\\\", \\\"laliga\\\",\\n    \\\"serie a\\\", \\\"italian serie a\\\", \\\"french ligue 1\\\", \\\"ligue 1\\\",\\n    \\\"primeira liga\\\", \\\"portugal primeira liga\\\", \\\"scottish premiership\\\",\\n    \\\"swiss super league\\\", \\\"switzerland super league\\\",\\n    \\\"brazil serie a\\\", \\\"brazilian serie a\\\", \\\"liga mx\\\",\\n    \\\"liga de expansion mx\\\", \\\"liga de expansión mx\\\", \\\"ascenso mx\\\",\\n    \\\"saudi pro league\\\",\\n})\\nCONDITIONAL = frozenset({\\n    \\\"czech first league\\\", \\\"czech first division\\\", \\\"ekstraklasa\\\",\\n    \\\"greek super league\\\", \\\"greece super league\\\", \\\"romanian liga i\\\",\\n    \\\"croatian hnl\\\", \\\"serbian superliga\\\", \\\"slovenian prvaliga\\\",\\n    \\\"slovak nike liga\\\", \\\"slovak niké liga\\\", \\\"hungarian nb i\\\",\\n    \\\"bulgarian first league\\\", \\\"ireland premier division\\\",\\n    \\\"republic of ireland premier division\\\", \\\"china super league\\\",\\n    \\\"chinese super league\\\", \\\"indian super league\\\", \\\"uae pro league\\\",\\n    \\\"qatar stars league\\\", \\\"peru liga 1\\\", \\\"bolivia primera division\\\",\\n    \\\"bolivian division profesional\\\", \\\"chile primera division\\\",\\n    \\\"colombia primera a\\\", \\\"ecuador ligapro serie a\\\",\\n    \\\"uruguay primera division\\\", \\\"russian premier league\\\",\\n})\\n# Names are never country-agnostic: \\\"Premier League\\\", \\\"Serie A\\\" and\\n# \\\"Bundesliga\\\" are used by many weak-data competitions.\\nREGISTERED_DIRECT = {\\n    \\\"netherlands\\\": {\\\"eredivisie\\\", \\\"netherlands eredivisie\\\", \\\"eerste divisie\\\", \\\"eerstedivisie\\\", \\\"netherlands eerste divisie\\\"},\\n    \\\"germany\\\": {\\\"bundesliga\\\", \\\"german bundesliga\\\"},\\n    \\\"belgium\\\": {\\\"belgian pro league\\\", \\\"belgian first division a\\\"},\\n    \\\"norway\\\": {\\\"eliteserien\\\", \\\"norwegian eliteserien\\\"},\\n    \\\"sweden\\\": {\\\"allsvenskan\\\", \\\"sweden allsvenskan\\\"},\\n    \\\"denmark\\\": {\\\"danish superliga\\\", \\\"superliga denmark\\\"},\\n    \\\"iceland\\\": {\\\"besta deild karla\\\", \\\"iceland premier league\\\"},\\n    \\\"austria\\\": {\\\"austrian bundesliga\\\", \\\"bundesliga\\\"},\\n    \\\"united states\\\": {\\\"mls\\\", \\\"major league soccer\\\"},\\n    \\\"usa\\\": {\\\"mls\\\", \\\"major league soccer\\\"},\\n    \\\"canada\\\": {\\\"mls\\\", \\\"major league soccer\\\"},\\n    \\\"australia\\\": {\\\"a-league men\\\", \\\"australia a-league men\\\"},\\n    \\\"england\\\": {\\\"premier league\\\", \\\"english premier league\\\"},\\n    \\\"spain\\\": {\\\"la liga\\\", \\\"laliga\\\"},\\n    \\\"italy\\\": {\\\"serie a\\\", \\\"italian serie a\\\"},\\n    \\\"france\\\": {\\\"french ligue 1\\\", \\\"ligue 1\\\"},\\n    \\\"portugal\\\": {\\\"primeira liga\\\", \\\"portugal primeira liga\\\"},\\n    \\\"scotland\\\": {\\\"scottish premiership\\\"},\\n    \\\"switzerland\\\": {\\\"swiss super league\\\", \\\"switzerland super league\\\"},\\n    \\\"brazil\\\": {\\\"serie a\\\", \\\"brazil serie a\\\", \\\"brazilian serie a\\\"},\\n    \\\"mexico\\\": {\\\"liga mx\\\", \\\"liga de expansion mx\\\", \\\"liga de expansión mx\\\", \\\"ascenso mx\\\"},\\n    \\\"saudi arabia\\\": {\\\"saudi pro league\\\"},\\n}\\nREGISTERED_CONDITIONAL = {\\n    \\\"czech republic\\\": {\\\"czech first league\\\", \\\"czech first division\\\"},\\n    \\\"poland\\\": {\\\"ekstraklasa\\\"},\\n    \\\"greece\\\": {\\\"greek super league\\\", \\\"greece super league\\\"},\\n    \\\"romania\\\": {\\\"romanian liga i\\\"},\\n    \\\"croatia\\\": {\\\"croatian hnl\\\"},\\n    \\\"serbia\\\": {\\\"serbian superliga\\\"},\\n    \\\"slovenia\\\": {\\\"slovenian prvaliga\\\"},\\n    \\\"slovakia\\\": {\\\"slovak nike liga\\\", \\\"slovak niké liga\\\"},\\n    \\\"hungary\\\": {\\\"hungarian nb i\\\"},\\n    \\\"bulgaria\\\": {\\\"bulgarian first league\\\"},\\n    \\\"ireland\\\": {\\\"ireland premier division\\\", \\\"republic of ireland premier division\\\"},\\n    \\\"republic of ireland\\\": {\\\"ireland premier division\\\", \\\"republic of ireland premier division\\\"},\\n    \\\"china\\\": {\\\"china super league\\\", \\\"chinese super league\\\"},\\n    \\\"india\\\": {\\\"indian super league\\\"},\\n    \\\"united arab emirates\\\": {\\\"uae pro league\\\"},\\n    \\\"uae\\\": {\\\"uae pro league\\\"},\\n    \\\"qatar\\\": {\\\"qatar stars league\\\"},\\n    \\\"peru\\\": {\\\"peru liga 1\\\"},\\n    \\\"bolivia\\\": {\\\"bolivia primera division\\\", \\\"bolivian division profesional\\\"},\\n    \\\"chile\\\": {\\\"chile primera division\\\"},\\n    \\\"colombia\\\": {\\\"colombia primera a\\\"},\\n    \\\"ecuador\\\": {\\\"ecuador ligapro serie a\\\"},\\n    \\\"uruguay\\\": {\\\"uruguay primera division\\\"},\\n    \\\"russia\\\": {\\\"russian premier league\\\"},\\n}\\n# Explicit user domestic exclusions are stricter than Tier-1 channel status.\\nEXCLUDED_DOMESTIC_COUNTRIES = frozenset({\\n    \\\"bangladesh\\\", \\\"israel\\\", \\\"kenya\\\", \\\"iraq\\\", \\\"wales\\\", \\\"kuwait\\\",\\n    \\\"finland\\\", \\\"japan\\\",\\n})\\nLOW_GOAL_DOMESTIC = frozenset({\\n    (\\\"vietnam\\\", \\\"v league 1\\\"), (\\\"south korea\\\", \\\"k league 1\\\"),\\n    (\\\"argentina\\\", \\\"argentina primera division\\\"),\\n    (\\\"argentina\\\", \\\"liga profesional\\\"),\\n})\\nVALID_KINDS = frozenset({\\n    \\\"DOMESTIC_LEAGUE\\\", \\\"DOMESTIC_CUP\\\", \\\"CONTINENTAL\\\",\\n    \\\"PROTECTED_OFFICIAL\\\", \\\"WOMENS_TOP_FLIGHT\\\",\\n})\\n# An actual top-level well-covered final is inspectable if provider proof\\n# exists; it is not auto-admitted and never authorizes a bookmaker quote.\\nCUP_INSPECTION = frozenset({\\n    \\\"australia cup\\\", \\\"fa cup\\\", \\\"efl cup\\\", \\\"dfb pokal\\\",\\n    \\\"copa del rey\\\", \\\"coppa italia\\\", \\\"coupe de france\\\",\\n    \\\"knvb beker\\\", \\\"portuguese cup\\\", \\\"taca de portugal\\\",\\n    \\\"us open cup\\\",\\n})\\n\\n\\ndef _name(s: Any) -> str:\\n    if not isinstance(s, str):\\n        return \\\"\\\"\\n    return re.sub(r\\\"\\\\s+\\\", \\\" \\\", re.sub(r\\\"[-_.]+\\\", \\\" \\\", s.casefold())).strip()\\n\\n\\ndef classify_competition(row: dict[str, Any]) -> dict[str, str]:\\n    if not isinstance(row, dict):\\n        raise ValueError(\\\"competition must be an object\\\")\\n    name = _name(row.get(\\\"competition_name\\\"))\\n    country = _name(row.get(\\\"country\\\"))\\n    kind = row.get(\\\"competition_kind\\\")\\n    if not name or not isinstance(kind, str) or kind not in VALID_KINDS:\\n        return {\\\"lane\\\": \\\"SCOPE_UNRESOLVED\\\", \\\"reason\\\": \\\"COMPETITION IDENTITY/KIND UNVERIFIED\\\"}\\n    if row.get(\\\"is_friendly\\\") is True or \\\"friendly\\\" in name or \\\"friendlies\\\" in name:\\n        return {\\\"lane\\\": \\\"SCOPE_EXCLUDED\\\", \\\"reason\\\": \\\"USER-SCOPE FRIENDLIES EXCLUDED\\\"}\\n    # Explicit user exceptions are only per-run, with original scope logged.\\n    override = row.get(\\\"user_one_run_override\\\") is True\\n    if kind == \\\"DOMESTIC_LEAGUE\\\":\\n        if country in EXCLUDED_DOMESTIC_COUNTRIES and not override:\\n            return {\\\"lane\\\": \\\"SCOPE_EXCLUDED\\\", \\\"reason\\\": \\\"EXPLICIT COUNTRY DOMESTIC LEAGUE EXCLUSION\\\"}\\n        if (country, name) in LOW_GOAL_DOMESTIC and not override:\\n            return {\\\"lane\\\": \\\"SCOPE_EXCLUDED\\\", \\\"reason\\\": \\\"LOW-GOAL DOMESTIC REGISTRY EXCLUSION\\\"}\\n        if country == \\\"germany\\\" and name in {\\\"3 liga\\\", \\\"3 liga germany\\\"} and not override:\\n            return {\\\"lane\\\": \\\"SCOPE_EXCLUDED\\\", \\\"reason\\\": \\\"GERMANY 3. LIGA USER EXCLUSION\\\"}\\n        if name in PRIORITY_NORMAL and name in REGISTERED_DIRECT.get(country, set()):\\n            return {\\\"lane\\\": \\\"ROUTINE_LEAGUE_PROFILE\\\", \\\"reason\\\": \\\"EXPLICIT COUNTRY+LEAGUE PRIORITY/NORMAL REGISTRY\\\"}\\n        if name in CONDITIONAL and name in REGISTERED_CONDITIONAL.get(country, set()):\\n            return {\\\"lane\\\": \\\"CONDITIONAL_CHEAP_GATE\\\", \\\"reason\\\": \\\"EXPLICIT COUNTRY+LEAGUE CONDITIONAL REGISTRY\\\"}\\n        return {\\\"lane\\\": \\\"SCOPE_EXCLUDED\\\", \\\"reason\\\": \\\"UNLISTED/WEAK-DATA DOMESTIC LEAGUE — NO RESEARCH\\\"}\\n    if kind == \\\"PROTECTED_OFFICIAL\\\" or kind == \\\"CONTINENTAL\\\":\\n        return {\\\"lane\\\": \\\"PROTECTED_CONTEXT_REVIEW\\\", \\\"reason\\\": \\\"SENIOR OFFICIAL COMPETITION — SOURCE/INCENTIVE CHECK\\\"}\\n    if kind == \\\"WOMENS_TOP_FLIGHT\\\":\\n        if country in EXCLUDED_DOMESTIC_COUNTRIES and not override:\\n            return {\\\"lane\\\": \\\"RAW_COVERAGE_ONLY\\\", \\\"reason\\\": \\\"USER EXCLUDED DOMESTIC WOMEN'S LEAGUE\\\"}\\n        return {\\\"lane\\\": \\\"COVERAGE_AUDIT_PROOF_REQUIRED\\\", \\\"reason\\\": \\\"WOMENS TOP-FLIGHT RAW COVERAGE, PROVE CHANNELS FOR WORK\\\"}\\n    if kind == \\\"DOMESTIC_CUP\\\":\\n        if name in CUP_INSPECTION:\\n            return {\\\"lane\\\": \\\"CUP_CHANNEL_REVIEW\\\", \\\"reason\\\": \\\"MAJOR SENIOR CUP — VERIFY STAGE/TEAMS/PROVIDER\\\"}\\n        return {\\\"lane\\\": \\\"RAW_COVERAGE_ONLY\\\", \\\"reason\\\": \\\"UNLISTED DOMESTIC CUP — NO DEEP ROUTINE SEARCH\\\"}\\n    raise AssertionError(kind)\\n\\n\\ndef screen_competitions(rows: list[dict[str, Any]]) -> dict[str, Any]:\\n    if not isinstance(rows, list):\\n        raise ValueError(\\\"competitions must be list\\\")\\n    buckets: dict[str, list[dict[str, Any]]] = {}\\n    seen: set[tuple[str, str, str]] = set()\\n    for i, row in enumerate(rows):\\n        decision = classify_competition(row)\\n        key = (_name(row.get(\\\"competition_name\\\")), _name(row.get(\\\"country\\\")),\\n               str(row.get(\\\"competition_kind\\\")))\\n        if key in seen:\\n            raise ValueError(f\\\"duplicate competition at index {i}: {key}\\\")\\n        seen.add(key)\\n        buckets.setdefault(decision[\\\"lane\\\"], []).append({**row, **decision})\\n    return {\\n        \\\"status\\\": \\\"COMPETITION PRE-SCREEN COMPLETE\\\",\\n        \\\"input_competition_count\\\": len(rows),\\n        \\\"blocks\\\": buckets,\\n        \\\"routine_verification_count\\\": sum(len(v) for k, v in buckets.items() if k in {\\n            \\\"ROUTINE_LEAGUE_PROFILE\\\", \\\"CONDITIONAL_CHEAP_GATE\\\",\\n            \\\"PROTECTED_CONTEXT_REVIEW\\\", \\\"CUP_CHANNEL_REVIEW\\\",\\n            \\\"COVERAGE_AUDIT_PROOF_REQUIRED\\\",\\n        }),\\n        \\\"raw_ledger_retained\\\": True,\\n    }\\n\",\"sweep_competition_scope_cli\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Pure scope preflight, no fixture-level searches or odds predictions.\\\"\\\"\\\"\\nfrom __future__ import annotations\\nimport argparse\\nimport json\\nimport sys\\nfrom pathlib import Path\\nfrom sweep_competition_scope import screen_competitions\\n\\ndef main() -> int:\\n    p=argparse.ArgumentParser()\\n    p.add_argument(\\\"--input\\\",required=True)\\n    args=p.parse_args()\\n    try:\\n        x=json.loads(Path(args.input).read_text(encoding=\\\"utf-8\\\"))\\n        if not isinstance(x,dict) or not isinstance(x.get(\\\"competitions\\\"),list):\\n            raise ValueError(\\\"competitions must be a list\\\")\\n        print(json.dumps(screen_competitions(x[\\\"competitions\\\"]),indent=2,sort_keys=True))\\n        return 0\\n    except (OSError,ValueError,json.JSONDecodeError) as e:\\n        print(json.dumps({\\\"ok\\\":False,\\\"reason\\\":str(e)}),file=sys.stderr)\\n        return 2\\n\\nif __name__==\\\"__main__\\\":\\n    raise SystemExit(main())\\n\",\"sweep_intake_evidence\":\"\\\"\\\"\\\"Fail-closed prospective evidence gate for the compact Football Step-0 Work queue.\\n\\nPure validation: no network, no model prediction, no source discovery.\\nLegacy/frozen handoffs do not invoke this module.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timedelta, timezone\\nfrom math import isfinite\\nimport re\\nfrom typing import Any\\nfrom urllib.parse import urlparse\\n\\n\\nLEAGUE_CHANNEL_POLICY = \\\"LEAGUE_CHANNEL_FIRST_V1\\\"\\n\\n# Operational data-coverage tier, NOT a goals/prediction tier or an\\n# automatic override of user scope / domestic league exclusions.\\n# Exact labels deliberately avoid ambiguous names such as \\\"Pro League\\\".\\nTIER1_CHANNEL_LEAGUES = frozenset({\\n    \\\"premier league\\\", \\\"english premier league\\\",\\n    \\\"bundesliga\\\", \\\"german bundesliga\\\",\\n    \\\"la liga\\\", \\\"laliga\\\", \\\"spanish la liga\\\",\\n    \\\"serie a\\\", \\\"italian serie a\\\",\\n    \\\"ligue 1\\\", \\\"french ligue 1\\\",\\n    \\\"eredivisie\\\", \\\"netherlands eredivisie\\\",\\n    \\\"primeira liga\\\", \\\"portugal primeira liga\\\",\\n    \\\"belgian pro league\\\", \\\"belgian first division a\\\",\\n    \\\"major league soccer\\\", \\\"mls\\\",\\n    \\\"liga mx\\\", \\\"mexico liga mx\\\",\\n    \\\"austrian bundesliga\\\",\\n    \\\"scottish premiership\\\",\\n    \\\"j1\\\", \\\"j1 league\\\", \\\"japan j1\\\",\\n    \\\"k league 1\\\", \\\"k1\\\", \\\"korean k league 1\\\",\\n})\\n\\nSUPPORTED_COMPETITION_TIERS = frozenset(\\n    {\\n        \\\"PROTECTED_OFFICIAL\\\",\\n        \\\"VERIFIED_PROFESSIONAL\\\",\\n        \\\"VERIFIED_WOMEN_TOP_FLIGHT\\\",\\n        \\\"MAJOR_SENIOR_DOMESTIC_CUP\\\",\\n        \\\"USER_EXCEPTION\\\",\\n    }\\n)\\n\\n# Source-backed expectation, not confirmed starting XI for a future kickoff.\\n# An official squad or dependable matchday-lineup provider is permitted for B.\\nXI_CHANNEL_TYPES = frozenset(\\n    {\\\"RECENT_CONFIRMED_XI\\\", \\\"PROVIDER_MATCHDAY_COVERAGE\\\", \\\"OFFICIAL_SQUAD_NEWS\\\"}\\n)\\nXI_STRONG_TYPES = frozenset(\\n    {\\\"RECENT_CONFIRMED_XI\\\", \\\"PROVIDER_MATCHDAY_COVERAGE\\\"}\\n)\\n\\nREQUIRED_MARKET_FIELDS = (\\n    \\\"asian_total_market_match_id\\\",\\n    \\\"asian_total_fixture_source_url\\\",\\n    \\\"asian_total_market_observed_at_utc\\\",\\n    \\\"asian_total_market_line\\\",\\n    \\\"asian_total_market_bookmaker\\\",\\n)\\n\\n\\ndef _nonempty(value: Any) -> bool:\\n    return isinstance(value, str) and bool(value.strip())\\n\\n\\ndef _source_url(value: Any) -> bool:\\n    if not _nonempty(value):\\n        return False\\n    try:\\n        uri = urlparse(value.strip())\\n    except (ValueError, AttributeError):\\n        return False\\n    return (\\n        uri.scheme == \\\"https\\\"\\n        and bool(uri.hostname)\\n        and \\\".\\\" in uri.hostname\\n        and not uri.username\\n        and not uri.password\\n    )\\n\\n\\ndef _utc_timestamp(value: Any) -> datetime | None:\\n    if not _nonempty(value):\\n        return None\\n    try:\\n        dt = datetime.fromisoformat(value.strip().replace(\\\"Z\\\", \\\"+00:00\\\"))\\n    except ValueError:\\n        return None\\n    if dt.tzinfo is None or dt.utcoffset() is None:\\n        return None\\n    return dt.astimezone(timezone.utc)\\n\\n\\ndef _league_channel_defects(row: dict[str, Any]) -> list[str]:\\n    \\\"\\\"\\\"Step-0 cheap league-profile admission, never an executable quote.\\\"\\\"\\\"\\n    defects: list[str] = []\\n    profile = row.get(\\\"league_channel_profile\\\")\\n    if not isinstance(profile, dict):\\n        return [\\\"LEAGUE_CHANNEL_PROFILE_MISSING\\\"]\\n    name = row.get(\\\"competition_name\\\") or row.get(\\\"competition\\\")\\n    profile_name = profile.get(\\\"competition_name\\\")\\n    if not _nonempty(name) or not _nonempty(profile_name) or (\\n        name.strip().casefold() != profile_name.strip().casefold()\\n    ):\\n        defects.append(\\\"LEAGUE_PROFILE_COMPETITION_MISMATCH\\\")\\n    kind = profile.get(\\\"profile_type\\\")\\n    if kind == \\\"TIER1_STANDARD\\\":\\n        if not _nonempty(name) or name.strip().casefold() not in TIER1_CHANNEL_LEAGUES:\\n            defects.append(\\\"LEAGUE_TIER1_NOT_ALLOWLISTED\\\")\\n    elif kind == \\\"PROVEN_LEAGUE\\\":\\n        for key in (\\\"recent_xi_fixture_count\\\", \\\"recent_asian_total_fixture_count\\\"):\\n            count = profile.get(key)\\n            if isinstance(count, bool) or not isinstance(count, int) or count < 2:\\n                defects.append(f\\\"LEAGUE_PROFILE_{key.upper()}_UNPROVEN\\\")\\n    else:\\n        defects.append(\\\"LEAGUE_PROFILE_TYPE_UNSUPPORTED\\\")\\n\\n    if profile.get(\\\"coverage_status\\\") != \\\"VERIFIED_CHANNELS\\\":\\n        defects.append(\\\"LEAGUE_CHANNEL_COVERAGE_UNVERIFIED\\\")\\n    if not _nonempty(profile.get(\\\"season\\\")):\\n        defects.append(\\\"LEAGUE_PROFILE_SEASON_MISSING\\\")\\n    if not _nonempty(profile.get(\\\"evidence_basis\\\")):\\n        defects.append(\\\"LEAGUE_PROFILE_EVIDENCE_BASIS_MISSING\\\")\\n    for key in (\\\"xi_provider_url\\\", \\\"asian_total_provider_url\\\", \\\"team_news_provider_url\\\"):\\n        if not _source_url(profile.get(key)):\\n            defects.append(f\\\"LEAGUE_{key.upper()}_MISSING\\\")\\n    if row.get(\\\"intake_evidence_scope\\\") != \\\"LEAGUE_CHANNEL_ONLY\\\":\\n        defects.append(\\\"LEAGUE_CHANNEL_SCOPE_NOT_DECLARED\\\")\\n    if row.get(\\\"xi_expected\\\") not in {\\\"YES\\\", \\\"UNCERTAIN\\\"}:\\n        defects.append(\\\"LEAGUE_XI_EXPECTATION_MISSING\\\")\\n    if row.get(\\\"xi_expected\\\") == \\\"UNCERTAIN\\\" and row.get(\\\"operational_viability_grade\\\") != \\\"B\\\":\\n        defects.append(\\\"XI_UNCERTAIN_MUST_BE_CONDITIONAL_B\\\")\\n    if row.get(\\\"market_observability\\\") not in {\\\"HIGH\\\", \\\"MEDIUM\\\"}:\\n        defects.append(\\\"LEAGUE_MARKET_COVERAGE_NOT_ESTABLISHED\\\")\\n    if row.get(\\\"team_news_observability\\\") not in {\\\"HIGH\\\", \\\"MEDIUM\\\"}:\\n        defects.append(\\\"LEAGUE_TEAM_NEWS_COVERAGE_NOT_ESTABLISHED\\\")\\n\\n    kickoff = _utc_timestamp(row.get(\\\"fixture_kickoff_utc\\\"))\\n    if row.get(\\\"fixture_identity_verified\\\") is not True or not _nonempty(row.get(\\\"match_id\\\")):\\n        defects.append(\\\"FIXTURE_IDENTITY_UNVERIFIED\\\")\\n    if kickoff is None:\\n        defects.append(\\\"FIXTURE_KICKOFF_UTC_UNVERIFIED\\\")\\n    evidence_time = _utc_timestamp(profile.get(\\\"evidence_checked_at_utc\\\"))\\n    if evidence_time is None or (\\n        kickoff and not timedelta(0) <= kickoff - evidence_time <= timedelta(days=30)\\n    ):\\n        defects.append(\\\"LEAGUE_PROFILE_EVIDENCE_STALE_OR_POST_KO\\\")\\n    recheck = _utc_timestamp(row.get(\\\"xi_recheck_due_utc\\\"))\\n    if recheck is None or (\\n        kickoff and not timedelta(minutes=30) <= kickoff - recheck <= timedelta(hours=3)\\n    ):\\n        defects.append(\\\"XI_PREMATCH_RECHECK_PLAN_MISSING_OR_INVALID\\\")\\n    if row.get(\\\"operational_viability_grade\\\") not in {\\\"A\\\", \\\"B\\\"}:\\n        defects.append(\\\"OPERATIONAL_GRADE_NOT_AB\\\")\\n    return defects\\n\\n\\ndef validate_shared_league_profiles(rows: list[dict[str, Any]]) -> list[str]:\\n    \\\"\\\"\\\"One immutable channel proof per competition in a new Step-0 sweep.\\n\\n    Reject a fixture-wise collection of different evidence profiles for the\\n    same league. This does not establish whether a URL is currently reachable:\\n    the caller must have actually checked its source before freezing it.\\n    \\\"\\\"\\\"\\n    known: dict[str, dict[str, Any]] = {}\\n    errors: list[str] = []\\n    for row in rows:\\n        if not isinstance(row, dict):\\n            errors.append(\\\"LEAGUE_CHANNEL_FIXTURE_ROW_INVALID\\\")\\n            continue\\n        name = row.get(\\\"competition_name\\\") or row.get(\\\"competition\\\")\\n        if not _nonempty(name):\\n            errors.append(\\\"LEAGUE_CHANNEL_COMPETITION_NAME_MISSING\\\")\\n            continue\\n        profile = row.get(\\\"league_channel_profile\\\")\\n        if not isinstance(profile, dict):\\n            errors.append(f\\\"LEAGUE_CHANNEL_PROFILE_MISSING: {name}\\\")\\n            continue\\n        key = name.strip().casefold()\\n        if key in known and known[key] != profile:\\n            errors.append(f\\\"LEAGUE_CHANNEL_PROFILE_INCONSISTENT: {name}\\\")\\n        else:\\n            known[key] = profile\\n    return sorted(set(errors))\\n\\n\\ndef validate_work_candidate(row: dict[str, Any], *, intake_policy: str = \\\"XI_MARKET_FIRST_V1\\\") -> list[str]:\\n    \\\"\\\"\\\"Return explicit operational proof defects, empty only when Work eligible.\\\"\\\"\\\"\\n    if not isinstance(row, dict):\\n        return [\\\"FIXTURE_ROW_INVALID\\\"]\\n\\n    if intake_policy not in {\\\"XI_MARKET_FIRST_V1\\\", LEAGUE_CHANNEL_POLICY}:\\n        return [\\\"UNKNOWN_STEP0_INTAKE_POLICY\\\"]\\n    defects: list[str] = []\\n    # Standing user scope (2026-10-09): all noncompetitive friendlies\\n    # are excluded before XI/market qualification, even when a bookmaker\\n    # lists them. Preserve competitive international qualifiers/tournaments.\\n    labels = (\\n        row.get(\\\"competition_name\\\"),\\n        row.get(\\\"competition\\\"),\\n        row.get(\\\"fixture_type\\\"),\\n        row.get(\\\"competition_type\\\"),\\n        row.get(\\\"match_type\\\"),\\n    )\\n    friendly_named = any(\\n        isinstance(value, str) and re.search(\\n            r\\\"\\\\b(?:friendly|friendlies|exhibition|pre[- ]?season)\\\\b\\\",\\n            value,\\n            flags=re.IGNORECASE,\\n        )\\n        for value in labels\\n    )\\n    if row.get(\\\"is_friendly\\\") is True or row.get(\\\"friendly_scope_excluded\\\") is True or friendly_named:\\n        defects.append(\\\"USER_SCOPE_EXCLUDED_FRIENDLY\\\")\\n\\n    if row.get(\\\"preflight_complete\\\") is not True:\\n        defects.append(\\\"STEP0_PREFLIGHT_INCOMPLETE\\\")\\n    if row.get(\\\"user_scope_excluded\\\") is True:\\n        defects.append(\\\"USER_SCOPE_EXCLUDED\\\")\\n    if row.get(\\\"hard_scope_excluded\\\") is True:\\n        defects.append(\\\"HARD_SCOPE_EXCLUDED\\\")\\n\\n    if row.get(\\\"competition_support_tier\\\") not in SUPPORTED_COMPETITION_TIERS:\\n        defects.append(\\\"COMPETITION_SUPPORT_UNVERIFIED\\\")\\n    if not _source_url(row.get(\\\"competition_official_url\\\")):\\n        defects.append(\\\"COMPETITION_SOURCE_MISSING\\\")\\n    if not _nonempty(row.get(\\\"competition_support_reason\\\")):\\n        defects.append(\\\"COMPETITION_SUPPORT_BASIS_MISSING\\\")\\n\\n    if intake_policy == LEAGUE_CHANNEL_POLICY:\\n        # Tier 1 and independently proven leagues need one reusable seasonal\\n        # lineup/Asian-total/news provider profile, not per-fixture book odds\\n        # or both clubs' prior XIs during /sweep. These become mandatory at\\n        # /rank and again at /xi before any official bet.\\n        return defects + _league_channel_defects(row)\\n\\n    # Legacy XI_MARKET_FIRST_V1 is unchanged for existing running/frozen sweeps.\\n    # 24h discovery occurs long before official match-day XIs drop. Require\\n    # evidence of a usable publication channel, NOT the future starting XI.\\n    # B/UNCERTAIN remains conditional until the /xi matchday recheck.\\n    xi_expected = row.get(\\\"xi_expected\\\")\\n    if xi_expected not in {\\\"YES\\\", \\\"UNCERTAIN\\\"}:\\n        defects.append(\\\"XI_CHANNEL_NOT_VERIFIABLE\\\")\\n    xi_types = []\\n    for side in (\\\"home\\\", \\\"away\\\"):\\n        kind = row.get(f\\\"xi_{side}_channel_type\\\")\\n        url = row.get(f\\\"xi_{side}_channel_source_url\\\")\\n        if kind not in XI_CHANNEL_TYPES or not _source_url(url):\\n            defects.append(f\\\"XI_{side.upper()}_PUBLISHING_CHANNEL_UNVERIFIED\\\")\\n        else:\\n            xi_types.append(kind)\\n    if xi_expected == \\\"YES\\\" and len(xi_types) == 2 and any(\\n        kind not in XI_STRONG_TYPES for kind in xi_types\\n    ):\\n        defects.append(\\\"XI_EXPECTATION_OVERSTATED\\\")\\n    if xi_expected == \\\"UNCERTAIN\\\":\\n        if row.get(\\\"operational_viability_grade\\\") != \\\"B\\\":\\n            defects.append(\\\"XI_UNCERTAIN_MUST_BE_CONDITIONAL_B\\\")\\n        # A squad list alone never establishes that starting XIs will be\\n        # obtainable. At least one evidenced provider/actual XI channel.\\n        if not any(kind in XI_STRONG_TYPES for kind in xi_types):\\n            defects.append(\\\"XI_CHANNEL_NO_PUBLISHING_PATH\\\")\\n    if not _nonempty(row.get(\\\"xi_channel_basis\\\")):\\n        defects.append(\\\"XI_CHANNEL_EVIDENCE_BASIS_MISSING\\\")\\n\\n    if row.get(\\\"market_observability\\\") not in {\\\"HIGH\\\", \\\"MEDIUM\\\"}:\\n        defects.append(\\\"CURRENT_ASIAN_TOTAL_UNAVAILABLE\\\")\\n    if not _nonempty(row.get(\\\"match_id\\\")) or (\\n        row.get(\\\"asian_total_market_match_id\\\") != row.get(\\\"match_id\\\")\\n    ):\\n        defects.append(\\\"CURRENT_ASIAN_TOTAL_FIXTURE_ID_MISMATCH\\\")\\n    if not _source_url(row.get(\\\"asian_total_fixture_source_url\\\")):\\n        defects.append(\\\"CURRENT_ASIAN_TOTAL_SOURCE_MISSING\\\")\\n    if not _nonempty(row.get(\\\"asian_total_market_bookmaker\\\")):\\n        defects.append(\\\"CURRENT_ASIAN_TOTAL_BOOKMAKER_MISSING\\\")\\n\\n    line = row.get(\\\"asian_total_market_line\\\")\\n    if isinstance(line, bool) or not isinstance(line, (int, float, str)):\\n        defects.append(\\\"CURRENT_ASIAN_TOTAL_LINE_MISSING\\\")\\n    else:\\n        try:\\n            numeric_line = float(line)\\n        except (ValueError, OverflowError):\\n            numeric_line = 0\\n        if not isfinite(numeric_line) or not 0.5 <= numeric_line <= 10.0:\\n            defects.append(\\\"CURRENT_ASIAN_TOTAL_LINE_MISSING\\\")\\n\\n    if row.get(\\\"team_news_observability\\\") not in {\\\"HIGH\\\", \\\"MEDIUM\\\"}:\\n        defects.append(\\\"TEAM_NEWS_NOT_OBSERVABLE\\\")\\n    if not _source_url(row.get(\\\"team_news_source_url\\\")):\\n        defects.append(\\\"TEAM_NEWS_SOURCE_MISSING\\\")\\n\\n    if row.get(\\\"fixture_identity_verified\\\") is not True:\\n        defects.append(\\\"FIXTURE_IDENTITY_UNVERIFIED\\\")\\n    kickoff = _utc_timestamp(row.get(\\\"fixture_kickoff_utc\\\"))\\n    if kickoff is None:\\n        defects.append(\\\"FIXTURE_KICKOFF_UTC_UNVERIFIED\\\")\\n\\n    market_time = _utc_timestamp(row.get(\\\"asian_total_market_observed_at_utc\\\"))\\n    if market_time is None:\\n        defects.append(\\\"CURRENT_ASIAN_TOTAL_TIME_UNVERIFIED\\\")\\n    # Optional corroborating previous XI provenance; if supplied, it must\\n    # precede the current fixture. Some tournaments lack recent historical XI.\\n    for side in (\\\"home\\\", \\\"away\\\"):\\n        source_match = row.get(f\\\"xi_{side}_recent_match_id\\\")\\n        source_kickoff_value = row.get(f\\\"xi_{side}_recent_match_kickoff_utc\\\")\\n        if source_match is not None or source_kickoff_value is not None:\\n            if not _nonempty(source_match) or source_match == row.get(\\\"match_id\\\"):\\n                defects.append(f\\\"XI_{side.upper()}_HISTORICAL_ID_INVALID\\\")\\n            source_kickoff = _utc_timestamp(source_kickoff_value)\\n            if source_kickoff is None or (\\n                kickoff and not (timedelta(0) < kickoff - source_kickoff <= timedelta(days=480))\\n            ):\\n                defects.append(f\\\"XI_{side.upper()}_HISTORICAL_FIXTURE_TIME_INVALID\\\")\\n\\n    recheck = _utc_timestamp(row.get(\\\"xi_recheck_due_utc\\\"))\\n    if recheck is None or (kickoff and not (\\n        timedelta(minutes=30) <= kickoff - recheck <= timedelta(hours=3)\\n    )):\\n        defects.append(\\\"XI_PREMATCH_RECHECK_PLAN_MISSING_OR_INVALID\\\")\\n\\n    if market_time and kickoff and not (\\n        timedelta(0) <= kickoff - market_time <= timedelta(hours=72)\\n    ):\\n        defects.append(\\\"CURRENT_ASIAN_TOTAL_STALE_OR_POST_KO\\\")\\n\\n    if row.get(\\\"operational_viability_grade\\\") not in {\\\"A\\\", \\\"B\\\"}:\\n        defects.append(\\\"OPERATIONAL_GRADE_NOT_AB\\\")\\n\\n    return defects\\n\\n\\ndef classify_preflight(row: dict[str, Any], *, intake_policy: str = \\\"XI_MARKET_FIRST_V1\\\") -> dict[str, Any]:\\n    \\\"\\\"\\\"Classify without deleting raw discovery or prematurely promoting UNKNOWN.\\\"\\\"\\\"\\n    defects = validate_work_candidate(row, intake_policy=intake_policy)\\n    if not defects:\\n        return {\\\"work_queue_eligible\\\": True, \\\"disposition\\\": \\\"READY_FOR_AB_QUEUE\\\", \\\"defects\\\": []}\\n    # Scope exclusions are terminal at classification, even when no\\n    # expensive XI/Asian-total preflight was attempted.\\n    if any(code in defects for code in (\\n        \\\"USER_SCOPE_EXCLUDED\\\", \\\"HARD_SCOPE_EXCLUDED\\\", \\\"USER_SCOPE_EXCLUDED_FRIENDLY\\\"\\n    )):\\n        return {\\n            \\\"work_queue_eligible\\\": False,\\n            \\\"disposition\\\": \\\"STEP0_OPERATIONAL_OR_SCOPE_EXCLUDED\\\",\\n            \\\"defects\\\": defects,\\n        }\\n    if not isinstance(row, dict) or row.get(\\\"preflight_complete\\\") is not True:\\n        return {\\n            \\\"work_queue_eligible\\\": False,\\n            \\\"disposition\\\": \\\"PREFLIGHT_INCOMPLETE_NO_WORK\\\",\\n            \\\"defects\\\": defects,\\n        }\\n    return {\\n        \\\"work_queue_eligible\\\": False,\\n        \\\"disposition\\\": \\\"STEP0_OPERATIONAL_OR_SCOPE_EXCLUDED\\\",\\n        \\\"defects\\\": defects,\\n    }\\n\",\"coverage_manifest\":\"from __future__ import annotations\\n\\nfrom dataclasses import dataclass\\nfrom typing import Any\\n\\n\\nMANIFEST_VERSION = \\\"required-competition-manifest-v1\\\"\\nREQUIRED_BLOCKS = (\\\"NED_EERSTE_DIVISIE\\\",)\\nVALID_STATUSES = {\\n    \\\"CHECKED_WITH_FIXTURES\\\",\\n    \\\"CHECKED_NO_IN_WINDOW_FIXTURES\\\",\\n    \\\"SOURCE_BLOCKED\\\",\\n}\\nVALID_DISPOSITIONS = {\\n    \\\"ADMITTED_TO_C\\\",\\n    \\\"HARD_EXCLUDED\\\",\\n    \\\"OPERATIONAL_EXCLUDED\\\",\\n    \\\"RESEARCHABILITY_EXCLUDED\\\",\\n    \\\"OPERATIONAL_CAPACITY_DEFERRED\\\",\\n    \\\"UNRESOLVED\\\",\\n}\\n\\n\\nclass CoverageManifestError(ValueError):\\n    pass\\n\\n\\ndef validate_required_competition_manifest(payload: dict[str, Any]) -> dict[str, Any]:\\n    version = payload.get(\\\"required_competition_manifest_version\\\")\\n    if version != MANIFEST_VERSION:\\n        raise CoverageManifestError(\\n            f\\\"required competition manifest version must be {MANIFEST_VERSION}\\\"\\n        )\\n\\n    blocks = payload.get(\\\"required_competition_blocks\\\")\\n    if not isinstance(blocks, list):\\n        raise CoverageManifestError(\\\"required_competition_blocks must be an array\\\")\\n\\n    by_id: dict[str, dict[str, Any]] = {}\\n    for block in blocks:\\n        if not isinstance(block, dict):\\n            raise CoverageManifestError(\\\"required competition block must be an object\\\")\\n        block_id = block.get(\\\"block_id\\\")\\n        if block_id in by_id:\\n            raise CoverageManifestError(f\\\"duplicate required competition block: {block_id}\\\")\\n        by_id[str(block_id)] = block\\n\\n    for required in REQUIRED_BLOCKS:\\n        if required not in by_id:\\n            raise CoverageManifestError(\\n                f\\\"HANDOFF INCOMPLETE — REQUIRED COMPETITION COVERAGE GAP: missing {required}\\\"\\n            )\\n\\n        block = by_id[required]\\n        status = block.get(\\\"status\\\")\\n        if status not in VALID_STATUSES:\\n            raise CoverageManifestError(f\\\"{required}: invalid status {status!r}\\\")\\n        if status == \\\"SOURCE_BLOCKED\\\":\\n            raise CoverageManifestError(\\n                f\\\"HANDOFF INCOMPLETE — REQUIRED COMPETITION COVERAGE GAP: {required} SOURCE_BLOCKED\\\"\\n            )\\n\\n        fixture_count = block.get(\\\"fixture_count\\\")\\n        fixtures = block.get(\\\"fixtures\\\")\\n        if not isinstance(fixture_count, int) or fixture_count < 0:\\n            raise CoverageManifestError(f\\\"{required}: fixture_count must be a non-negative integer\\\")\\n        if not isinstance(fixtures, list):\\n            raise CoverageManifestError(f\\\"{required}: fixtures must be an array\\\")\\n        if fixture_count != len(fixtures):\\n            raise CoverageManifestError(\\n                f\\\"{required}: fixture_count {fixture_count} != fixture list {len(fixtures)}\\\"\\n            )\\n\\n        if status == \\\"CHECKED_NO_IN_WINDOW_FIXTURES\\\" and fixture_count != 0:\\n            raise CoverageManifestError(\\n                f\\\"{required}: CHECKED_NO_IN_WINDOW_FIXTURES requires fixture_count=0\\\"\\n            )\\n        if status == \\\"CHECKED_WITH_FIXTURES\\\" and fixture_count == 0:\\n            raise CoverageManifestError(\\n                f\\\"{required}: CHECKED_WITH_FIXTURES requires at least one fixture\\\"\\n            )\\n\\n        seen_match_ids: set[str] = set()\\n        for fixture in fixtures:\\n            if not isinstance(fixture, dict):\\n                raise CoverageManifestError(f\\\"{required}: fixture must be an object\\\")\\n            match_id = str(fixture.get(\\\"match_id\\\", \\\"\\\")).strip()\\n            if not match_id:\\n                raise CoverageManifestError(f\\\"{required}: fixture missing match_id\\\")\\n            if match_id in seen_match_ids:\\n                raise CoverageManifestError(f\\\"{required}: duplicate match_id {match_id}\\\")\\n            seen_match_ids.add(match_id)\\n            if not str(fixture.get(\\\"match\\\", \\\"\\\")).strip():\\n                raise CoverageManifestError(f\\\"{required}: fixture missing match\\\")\\n            if not str(fixture.get(\\\"kickoff_ict\\\", \\\"\\\")).strip():\\n                raise CoverageManifestError(f\\\"{required}: fixture missing kickoff_ict\\\")\\n            disposition = fixture.get(\\\"disposition\\\")\\n            if disposition not in VALID_DISPOSITIONS:\\n                raise CoverageManifestError(\\n                    f\\\"{required}: fixture {match_id} has invalid disposition {disposition!r}\\\"\\n                )\\n\\n    return {\\n        \\\"version\\\": version,\\n        \\\"required_blocks_complete\\\": True,\\n        \\\"required_blocks\\\": list(REQUIRED_BLOCKS),\\n    }\\n\",\"step0_handoff_cli\":\"from __future__ import annotations\\n\\nimport argparse\\nimport json\\nimport sys\\nfrom pathlib import Path\\nfrom typing import Any\\n\\nfrom sweep_intake_evidence import validate_work_candidate, validate_shared_league_profiles\\n\\nHANDOFF_VERSION = \\\"football-step0-handoff-v2\\\"\\nFIELDS = (\\n    \\\"xi_expected\\\",\\n    \\\"market_observability\\\",\\n    \\\"team_news_observability\\\",\\n    \\\"operational_viability_reason\\\",\\n    \\\"competition_reliability_state\\\",\\n    \\\"competition_reliability_reason\\\",\\n)\\nSOURCE_SCOPES = {\\\"EXACT_DATE_UNIVERSE\\\", \\\"BOUNDED_PRODUCTION_DISCOVERY\\\"}\\n\\n\\nclass Step0HandoffError(ValueError):\\n    pass\\n\\n\\ndef _mid(row: dict[str, Any]) -> str:\\n    value = row.get(\\\"match_id\\\")\\n    if not isinstance(value, str) or not value.strip():\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — STABLE FIXTURE ID MISSING\\\"\\n        )\\n    return value.strip()\\n\\n\\ndef _nonempty(value: Any, field: str) -> str:\\n    if not isinstance(value, str) or not value.strip():\\n        raise Step0HandoffError(\\n            f\\\"HANDOFF INCOMPLETE — {field} missing\\\"\\n        )\\n    return value.strip()\\n\\n\\ndef _manifest_sources(manifest: Any) -> tuple[list[dict[str, Any]], str]:\\n    \\\"\\\"\\\"Normalize supported discovery-seed manifest encodings.\\n\\n    Step 0 historically emitted both:\\n    - {\\\"sources\\\": [...]} wrapper objects; and\\n    - a direct [...] array of source-entry objects.\\n\\n    They carry the same source provenance and must not create a Step0->Step1\\n    compatibility failure. Structural/source-family checks remain identical.\\n    \\\"\\\"\\\"\\n    if isinstance(manifest, dict):\\n        sources = manifest.get(\\\"sources\\\")\\n        shape = \\\"OBJECT\\\"\\n    elif isinstance(manifest, list):\\n        sources = manifest\\n        shape = \\\"ARRAY\\\"\\n    else:\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — discovery_seed_manifest must be an object \\\"\\n            \\\"with sources or a source-entry array\\\"\\n        )\\n\\n    if not isinstance(sources, list) or len(sources) < 2:\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — bounded source scope requires at least \\\"\\n            \\\"two discovery seed sources\\\"\\n        )\\n\\n    normalized: list[dict[str, Any]] = []\\n    for source in sources:\\n        if not isinstance(source, dict):\\n            raise Step0HandoffError(\\n                \\\"HANDOFF INCOMPLETE — discovery seed source must be an object\\\"\\n            )\\n        normalized.append(source)\\n\\n    return normalized, shape\\n\\n\\ndef _validate_source_contract(payload: dict[str, Any], *, consumer: str) -> tuple[str, str]:\\n    \\\"\\\"\\\"Validate Step-0 source semantics consumed by /rank.\\n\\n    Older v2 handoffs may predate source_scope. They remain readable as\\n    LEGACY_EXACT_OR_PRE_SCOPE so historical completed handoffs are not broken.\\n    Every new bounded-production handoff is validated explicitly.\\n    \\\"\\\"\\\"\\n    scope = payload.get(\\\"source_scope\\\")\\n    if scope is None:\\n        return \\\"LEGACY_EXACT_OR_PRE_SCOPE\\\", \\\"LEGACY_PRE_SCOPE\\\"\\n\\n    if scope not in SOURCE_SCOPES:\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — source_scope must be \\\"\\n            \\\"EXACT_DATE_UNIVERSE or BOUNDED_PRODUCTION_DISCOVERY\\\"\\n        )\\n\\n    _nonempty(payload.get(\\\"source_transport\\\"), \\\"source_transport\\\")\\n\\n    if scope == \\\"EXACT_DATE_UNIVERSE\\\":\\n        if payload.get(\\\"global_raw_exact\\\") is False:\\n            raise Step0HandoffError(\\n                \\\"HANDOFF INCOMPLETE — EXACT_DATE_UNIVERSE cannot set \\\"\\n                \\\"global_raw_exact=false\\\"\\n            )\\n        return scope, \\\"EXACT_SOURCE_PROVENANCE_PRESENT\\\"\\n\\n    # New FAST_PRODUCTION fallback contract.\\n    if payload.get(\\\"coverage_mode\\\") != \\\"FALLBACK_PRODUCTION_SCOPE\\\":\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — bounded source scope requires \\\"\\n            \\\"coverage_mode=FALLBACK_PRODUCTION_SCOPE\\\"\\n        )\\n    if payload.get(\\\"global_raw_exact\\\") is not False:\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — bounded source scope requires \\\"\\n            \\\"global_raw_exact=false\\\"\\n        )\\n    if payload.get(\\\"production_scope_complete\\\") is not True:\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — bounded source scope requires \\\"\\n            \\\"production_scope_complete=true\\\"\\n        )\\n    if payload.get(\\\"source_transport\\\") != \\\"MULTISOURCE_BOUNDED_PRODUCTION_DISCOVERY\\\":\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — bounded source scope requires \\\"\\n            \\\"source_transport=MULTISOURCE_BOUNDED_PRODUCTION_DISCOVERY\\\"\\n        )\\n\\n    production_universe_count = payload.get(\\\"production_universe_count\\\")\\n    if (\\n        isinstance(production_universe_count, bool)\\n        or not isinstance(production_universe_count, int)\\n        or production_universe_count < 0\\n    ):\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — bounded source scope requires exact \\\"\\n            \\\"production_universe_count\\\"\\n        )\\n\\n    manifest = payload.get(\\\"discovery_seed_manifest\\\")\\n    block_summary = payload.get(\\\"block_excluded_summary\\\")\\n\\n    # Export validation is strict. Every newly produced bounded Step-0 handoff\\n    # must preserve its source manifest and block-exclusion audit metadata.\\n    # The manifest may use either supported serialization: a wrapper object\\n    # with \\\"sources\\\" or a direct array of source-entry objects.\\n    if consumer == \\\"export\\\":\\n        if manifest is None:\\n            raise Step0HandoffError(\\n                \\\"HANDOFF INCOMPLETE — bounded source scope missing \\\"\\n                \\\"discovery_seed_manifest\\\"\\n            )\\n        if not isinstance(block_summary, (list, dict)):\\n            raise Step0HandoffError(\\n                \\\"HANDOFF INCOMPLETE — bounded source scope requires \\\"\\n                \\\"block_excluded_summary\\\"\\n            )\\n\\n    # /rank is allowed to consume a transitional bounded handoff that was\\n    # already fully reconciled before the manifest requirement was added.\\n    # Missing provenance is audit debt, not a reason to throw away a frozen\\n    # production universe and capacity queue. The predictive inputs below\\n    # remain fully fail-closed.\\n    if manifest is None and consumer == \\\"rank\\\":\\n        return scope, \\\"LEGACY_MISSING_DISCOVERY_SEED_MANIFEST\\\"\\n\\n    manifest_shape = \\\"NONE\\\"\\n    if manifest is not None:\\n        sources, manifest_shape = _manifest_sources(manifest)\\n\\n        families = set()\\n        for source in sources:\\n            family_value = source.get(\\\"family\\\", source.get(\\\"source_family\\\"))\\n            family = _nonempty(\\n                family_value, \\\"discovery seed source family\\\"\\n            )\\n            families.add(family.casefold())\\n\\n        if len(families) < 2:\\n            raise Step0HandoffError(\\n                \\\"HANDOFF INCOMPLETE — bounded source scope requires at least \\\"\\n                \\\"two independent source families\\\"\\n            )\\n\\n    if consumer == \\\"rank\\\" and block_summary is None:\\n        return scope, \\\"LEGACY_MISSING_BLOCK_EXCLUDED_SUMMARY\\\"\\n\\n    return scope, f\\\"BOUNDED_SOURCE_PROVENANCE_PRESENT_{manifest_shape}\\\"\\n\\n\\ndef validate_step0_handoff(payload: dict[str, Any], *, consumer: str = \\\"export\\\") -> dict[str, Any]:\\n    if payload.get(\\\"handoff_version\\\") != HANDOFF_VERSION:\\n        raise Step0HandoffError(\\n            f\\\"handoff_version must be {HANDOFF_VERSION}\\\"\\n        )\\n\\n    for key in (\\\"complete\\\", \\\"actionable_complete\\\", \\\"work_ready\\\"):\\n        if payload.get(key) is not True:\\n            raise Step0HandoffError(\\n                f\\\"HANDOFF INCOMPLETE — {key}=true required\\\"\\n            )\\n\\n    if consumer not in {\\\"export\\\", \\\"rank\\\"}:\\n        raise Step0HandoffError(\\\"consumer must be export or rank\\\")\\n\\n    # A fast-finish handoff may not erase unresolved source evidence just\\n    # because its bounded verification attempts have been exhausted.\\n    verification_policy = payload.get(\\\"verification_policy\\\")\\n    if verification_policy not in (None, \\\"FAST_FINISH_V1\\\"):\\n        raise Step0HandoffError(\\\"HANDOFF INCOMPLETE — unknown verification policy\\\")\\n    if verification_policy == \\\"FAST_FINISH_V1\\\":\\n        unresolved = payload.get(\\\"terminal_unresolved_verification_blocks\\\")\\n        if not isinstance(unresolved, list):\\n            raise Step0HandoffError(\\\"HANDOFF INCOMPLETE — fast-finish unresolved-block manifest missing\\\")\\n        if unresolved:\\n            raise Step0HandoffError(\\n                \\\"HANDOFF INCOMPLETE — FAST FINISH UNRESOLVED: \\\"\\n                + \\\", \\\".join(str(x) for x in unresolved)\\n            )\\n\\n    source_scope, source_manifest_status = _validate_source_contract(\\n        payload, consumer=consumer\\n    )\\n\\n    # FAST_FINISH is a producer/consumer contract, not permission to export\\n    # a provisional JSON with its completion booleans altered. Confirm\\n    # required-competition fixture rows against a separately frozen source\\n    # inventory; a block summary stating '10 fixtures' is not enough.\\n    if verification_policy == \\\"FAST_FINISH_V1\\\":\\n        from coverage_manifest import (\\n            CoverageManifestError,\\n            validate_required_competition_manifest,\\n        )\\n        if payload.get(\\\"required_competition_blocks_complete\\\") is not True:\\n            raise Step0HandoffError(\\n                \\\"HANDOFF INCOMPLETE — REQUIRED COMPETITION BLOCKS NOT COMPLETE\\\"\\n            )\\n        try:\\n            validate_required_competition_manifest(payload)\\n        except CoverageManifestError as exc:\\n            raise Step0HandoffError(str(exc)) from exc\\n        source_ids = payload.get(\\\"required_competition_source_fixture_ids\\\")\\n        if not isinstance(source_ids, dict):\\n            raise Step0HandoffError(\\n                \\\"HANDOFF INCOMPLETE — INDEPENDENT REQUIRED FIXTURE INVENTORY MISSING\\\"\\n            )\\n        for block in payload[\\\"required_competition_blocks\\\"]:\\n            if block[\\\"block_id\\\"] != \\\"NED_EERSTE_DIVISIE\\\":\\n                continue\\n            observed = source_ids.get(block[\\\"block_id\\\"])\\n            expected = [row[\\\"match_id\\\"] for row in block[\\\"fixtures\\\"]]\\n            if (\\n                not isinstance(observed, list)\\n                or len(observed) != len(set(observed))\\n                or set(observed) != set(expected)\\n                or len(observed) != len(expected)\\n            ):\\n                raise Step0HandoffError(\\n                    \\\"HANDOFF INCOMPLETE — NETHERLANDS EERSTE DIVISIE \\\"\\n                    \\\"SOURCE INVENTORY / FIXTURE MANIFEST MISMATCH\\\"\\n                )\\n\\n    admitted = payload.get(\\\"admitted_fixtures\\\")\\n    queue = payload.get(\\\"capacity_queue\\\")\\n    if not isinstance(admitted, list):\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — admitted_fixtures missing\\\"\\n        )\\n    if not isinstance(queue, list):\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — STEP0 CAPACITY QUEUE MISSING\\\"\\n        )\\n    policy = payload.get('sweep_work_budget_policy')\\n    if policy not in (None, 'COMPACT_GOAL_ROUTE_V1'):\\n        raise Step0HandoffError('HANDOFF INCOMPLETE: unknown budget policy')\\n    scope_policy = payload.get(\\\"competition_scope_policy\\\")\\n    if scope_policy not in (None, \\\"REGISTRY_FIRST_V1\\\"):\\n        raise Step0HandoffError(\\\"HANDOFF INCOMPLETE — unknown competition scope policy\\\")\\n    if scope_policy == \\\"REGISTRY_FIRST_V1\\\":\\n        from sweep_competition_scope import screen_competitions\\n        scope_rows = payload.get(\\\"competition_scope_blocks\\\")\\n        if not isinstance(scope_rows, list):\\n            raise Step0HandoffError(\\n                \\\"HANDOFF INCOMPLETE — registry-first competition block manifest missing\\\"\\n            )\\n        screening = screen_competitions(scope_rows)\\n        prohibited = {\\n            (str(z.get(\\\"competition_name\\\", \\\"\\\")).casefold(), str(z.get(\\\"country\\\", \\\"\\\")).casefold())\\n            for lane in (\\\"SCOPE_EXCLUDED\\\", \\\"RAW_COVERAGE_ONLY\\\", \\\"SCOPE_UNRESOLVED\\\")\\n            for z in screening[\\\"blocks\\\"].get(lane, [])\\n        }\\n        all_work = payload.get(\\\"capacity_queue\\\", [])\\n        if not isinstance(all_work, list):\\n            raise Step0HandoffError(\\\"HANDOFF INCOMPLETE — capacity queue invalid\\\")\\n        for item in all_work:\\n            if not isinstance(item, dict):\\n                raise Step0HandoffError(\\\"HANDOFF INCOMPLETE — queue fixture invalid\\\")\\n            key = (str(item.get(\\\"competition_name\\\", \\\"\\\")).casefold(),\\n                   str(item.get(\\\"country\\\", \\\"\\\")).casefold())\\n            if key in prohibited:\\n                raise Step0HandoffError(\\n                    \\\"HANDOFF INCOMPLETE — SCOPE EXCLUDED DOMESTIC LEAGUE LEAK: \\\"\\n                    + str(item.get(\\\"match_id\\\", \\\"\\\"))\\n                )\\n        candidate_labels = {\\n            (str(z.get(\\\"competition_name\\\", \\\"\\\")).casefold(), str(z.get(\\\"country\\\", \\\"\\\")).casefold())\\n            for z in scope_rows\\n        }\\n        for item in all_work:\\n            key = (str(item.get(\\\"competition_name\\\", \\\"\\\")).casefold(),\\n                   str(item.get(\\\"country\\\", \\\"\\\")).casefold())\\n            if key not in candidate_labels:\\n                raise Step0HandoffError(\\n                    \\\"HANDOFF INCOMPLETE — WORK FIXTURE MISSING COMPETITION BLOCK SCOPE: \\\"\\n                    + str(item.get(\\\"match_id\\\", \\\"\\\"))\\n                )\\n\\n    intake_policy = payload.get(\\\"strict_intake_policy\\\")\\n    if intake_policy not in (None, \\\"XI_MARKET_FIRST_V1\\\", \\\"LEAGUE_CHANNEL_FIRST_V1\\\"):\\n        raise Step0HandoffError(\\\"HANDOFF INCOMPLETE — unknown strict intake policy\\\")\\n    strict_xi_market_gate = (\\n        policy == \\\"COMPACT_GOAL_ROUTE_V1\\\"\\n        or intake_policy == \\\"XI_MARKET_FIRST_V1\\\"\\n    )\\n    limit = 8 if policy == 'COMPACT_GOAL_ROUTE_V1' else 15\\n    if len(admitted) > limit:\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — OPERATIONAL CAPACITY BREACH\\\"\\n        )\\n\\n    admitted_ids = set()\\n    for row in admitted:\\n        match_id = _mid(row)\\n        admitted_ids.add(match_id)\\n        if row.get(\\\"operational_viability_grade\\\") not in {\\\"A\\\", \\\"B\\\"}:\\n            raise Step0HandoffError(\\n                f\\\"HANDOFF INCOMPLETE — {match_id} not grade A/B\\\"\\n            )\\n        for key in FIELDS:\\n            if not isinstance(row.get(key), str) or not row[key].strip():\\n                raise Step0HandoffError(\\n                    \\\"HANDOFF INCOMPLETE — STEP0 OPERATIONAL CONTRACT MISSING: \\\"\\n                    f\\\"{match_id} missing {key}\\\"\\n                )\\n\\n    if intake_policy == \\\"LEAGUE_CHANNEL_FIRST_V1\\\":\\n        shared_errors = validate_shared_league_profiles(queue)\\n        if shared_errors:\\n            raise Step0HandoffError(\\n                \\\"HANDOFF INCOMPLETE — SHARED LEAGUE CHANNEL PROFILE: \\\"\\n                + \\\"; \\\".join(shared_errors)\\n            )\\n    queue_ids = set()\\n    ranks = set()\\n    for row in queue:\\n        match_id = _mid(row)\\n        if match_id in queue_ids:\\n            raise Step0HandoffError(\\n                f\\\"HANDOFF INCOMPLETE — DUPLICATE QUEUE FIXTURE ID: {match_id}\\\"\\n            )\\n        queue_ids.add(match_id)\\n\\n        disposition = row.get(\\n            \\\"final_step0_disposition\\\", row.get(\\\"disposition\\\")\\n        )\\n        if disposition not in {\\n            \\\"ADMITTED_TO_C\\\",\\n            \\\"OPERATIONAL_CAPACITY_DEFERRED\\\",\\n        }:\\n            raise Step0HandoffError(\\n                f\\\"HANDOFF INCOMPLETE — invalid queue disposition: {match_id}\\\"\\n            )\\n\\n        for key in FIELDS:\\n            if not isinstance(row.get(key), str) or not row[key].strip():\\n                raise Step0HandoffError(\\n                    \\\"HANDOFF INCOMPLETE — STEP0 OPERATIONAL CONTRACT MISSING: \\\"\\n                    f\\\"{match_id} missing {key}\\\"\\n                )\\n\\n        if strict_xi_market_gate:\\n            defects = validate_work_candidate(\\n                row, intake_policy=intake_policy or \\\"XI_MARKET_FIRST_V1\\\"\\n            )\\n            if defects:\\n                raise Step0HandoffError(\\n                    \\\"HANDOFF INCOMPLETE — XI/ASIAN-TOTAL INTAKE EVIDENCE: \\\"\\n                    f\\\"{match_id}: {', '.join(defects)}\\\"\\n                )\\n\\n        rank = row.get(\\\"step0_capacity_queue_rank\\\")\\n        if (\\n            isinstance(rank, bool)\\n            or not isinstance(rank, int)\\n            or rank < 1\\n            or rank in ranks\\n        ):\\n            raise Step0HandoffError(\\n                \\\"HANDOFF INCOMPLETE — STEP0 CAPACITY QUEUE INVALID: \\\"\\n                f\\\"{match_id}\\\"\\n            )\\n        ranks.add(rank)\\n\\n    if ranks != set(range(1, len(queue) + 1)):\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — STEP0 CAPACITY QUEUE INVALID: \\\"\\n            \\\"ranks not contiguous\\\"\\n        )\\n\\n    if not admitted_ids.issubset(queue_ids):\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — STEP0 CAPACITY QUEUE MISSING \\\"\\n            f\\\"ADMITTED FIXTURES: {sorted(admitted_ids - queue_ids)}\\\"\\n        )\\n\\n    if policy == 'COMPACT_GOAL_ROUTE_V1':\\n        expected = { _mid(row) for row in queue if row['step0_capacity_queue_rank'] <= 8 }\\n        if admitted_ids != expected:\\n            raise Step0HandoffError('HANDOFF INCOMPLETE: compact ranks 1-8 must be admitted')\\n        for row in queue:\\n            rank = row['step0_capacity_queue_rank']\\n            disposition = row.get('final_step0_disposition', row.get('disposition'))\\n            required = 'ADMITTED_TO_C' if rank <= 8 else 'OPERATIONAL_CAPACITY_DEFERRED'\\n            if disposition != required:\\n                raise Step0HandoffError(\\n                    f'HANDOFF INCOMPLETE: compact queue disposition inconsistent at rank {rank}'\\n                )\\n\\n    if payload.get(\\\"admitted_to_c_count\\\") != len(admitted):\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — admitted count mismatch\\\"\\n        )\\n\\n    deferred = sum(\\n        row.get(\\\"final_step0_disposition\\\", row.get(\\\"disposition\\\"))\\n        == \\\"OPERATIONAL_CAPACITY_DEFERRED\\\"\\n        for row in queue\\n    )\\n    if payload.get(\\\"capacity_deferred_count\\\") != deferred:\\n        raise Step0HandoffError(\\n            \\\"HANDOFF INCOMPLETE — deferred count mismatch\\\"\\n        )\\n\\n    return {\\n        \\\"step0_handoff_validation_status\\\": \\\"PASS\\\",\\n        \\\"source_scope\\\": source_scope,\\n        \\\"source_manifest_status\\\": source_manifest_status,\\n        \\\"consumer\\\": consumer,\\n        \\\"admitted_count\\\": len(admitted),\\n        \\\"capacity_queue_count\\\": len(queue),\\n        \\\"capacity_deferred_count\\\": deferred,\\n    }\\n\\n\\ndef main() -> int:\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--input\\\", required=True)\\n    parser.add_argument(\\n        \\\"--consumer\\\",\\n        choices=(\\\"export\\\", \\\"rank\\\"),\\n        default=\\\"export\\\",\\n        help=\\\"export=strict Step-0 packaging validation; rank=consumer compatibility\\\",\\n    )\\n    args = parser.parse_args()\\n\\n    try:\\n        payload = json.loads(\\n            Path(args.input).read_text(encoding=\\\"utf-8\\\")\\n        )\\n        out = validate_step0_handoff(payload, consumer=args.consumer)\\n    except (OSError, json.JSONDecodeError, Step0HandoffError) as exc:\\n        print(\\n            json.dumps({\\\"ok\\\": False, \\\"error\\\": str(exc)}),\\n            file=sys.stderr,\\n        )\\n        return 2\\n\\n    print(json.dumps({\\\"ok\\\": True, **out}, indent=2))\\n    return 0\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    raise SystemExit(main())\\n\",\"step0_package_cli\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Create a STEP0 Work ZIP *only* after final source-ledger read-back and validation.\\n\\nA provisional artifact is NOT a rankable handoff, even if it has 8 fixtures.\\nThe run-proof JSON is supplied by independent Airtable read-back; this local\\ncommand cannot itself confirm remote source freshness.\\n\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport hashlib\\nimport json\\nimport os\\nimport sys\\nimport tempfile\\nimport zipfile\\nfrom pathlib import Path\\n\\nfrom step0_handoff_cli import Step0HandoffError, validate_step0_handoff\\n\\n\\ndef validate_run_proof(handoff: dict, run: dict) -> None:\\n    if not isinstance(run, dict):\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — missing independent Sweep Runs read-back\\\")\\n    run_id = handoff.get(\\\"run_id\\\")\\n    if not isinstance(run_id, str) or not run_id.startswith(\\\"SWEEP-\\\"):\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — handoff run_id missing\\\")\\n    if run.get(\\\"run_id\\\") != run_id:\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — Sweep Runs identity mismatch\\\")\\n    if run.get(\\\"run_status\\\") != \\\"RUNNING\\\" or run.get(\\\"phase\\\") != \\\"PACKAGING\\\":\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — source run must be RUNNING/PACKAGING\\\")\\n    if run.get(\\\"reconciliation_complete\\\") is not True:\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — Step 0 reconciliation not complete\\\")\\n    if run.get(\\\"capacity_queue_frozen\\\") is not True:\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — capacity queue not frozen\\\")\\n    if run.get(\\\"required_competition_blocks_complete\\\") is not True:\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — required-competition coverage not complete\\\")\\n    if run.get(\\\"pending_verification_blocks\\\") != 0 or run.get(\\\"unresolved_count\\\") != 0:\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — unresolved/pending source evidence\\\")\\n    if run.get(\\\"source_payload_hash\\\") != handoff.get(\\\"source_payload_hash\\\"):\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — source epoch hash mismatch\\\")\\n    if run.get(\\\"admitted_count\\\") != len(handoff.get(\\\"admitted_fixtures\\\", [])):\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — Airtable admitted count mismatch\\\")\\n    if run.get(\\\"production_universe_count\\\") != handoff.get(\\\"production_universe_count\\\"):\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — source coverage count mismatch\\\")\\n    if handoff.get(\\\"verification_policy\\\") == \\\"FAST_FINISH_V1\\\":\\n        from coverage_manifest import REQUIRED_BLOCKS\\n        ledger = run.get(\\\"required_competition_source_fixture_ids\\\")\\n        if not isinstance(ledger, dict):\\n            raise Step0HandoffError(\\\"PACKAGE BLOCKED — required fixture source ledger missing\\\")\\n        for block in REQUIRED_BLOCKS:\\n            if ledger.get(block) != handoff.get(\\\"required_competition_source_fixture_ids\\\", {}).get(block):\\n                raise Step0HandoffError(\\\"PACKAGE BLOCKED — source ledger / handoff identity disagreement\\\")\\n        # A proposed Work queue is not frozen merely because eight B grades\\n        # exist. Every admitted row needs a matching finalized Airtable state.\\n        persisted = run.get(\\\"admitted_dispositions\\\")\\n        if not isinstance(persisted, dict):\\n            raise Step0HandoffError(\\\"PACKAGE BLOCKED — persisted Work admissions missing\\\")\\n        admitted_ids = {x.get(\\\"match_id\\\") for x in handoff[\\\"admitted_fixtures\\\"]}\\n        if admitted_ids != set(persisted) or any(\\n            persisted[mid] != \\\"ADMITTED_TO_C\\\" for mid in admitted_ids\\n        ):\\n            raise Step0HandoffError(\\\"PACKAGE BLOCKED — admitted fixture rows still provisional\\\")\\n\\n\\ndef package(handoff_path: Path, note_path: Path, proof_path: Path, output: Path) -> dict:\\n    handoff = json.loads(handoff_path.read_text(encoding=\\\"utf-8\\\"))\\n    proof = json.loads(proof_path.read_text(encoding=\\\"utf-8\\\"))\\n    result = validate_step0_handoff(handoff, consumer=\\\"export\\\")\\n    validate_run_proof(handoff, proof)\\n    if result[\\\"step0_handoff_validation_status\\\"] != \\\"PASS\\\":\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — handoff validator did not pass\\\")\\n    # Do not hide model/scoring work inside a provisional text file.\\n    text = note_path.read_text(encoding=\\\"utf-8\\\")\\n    if not text.strip():\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — human-readable handoff empty\\\")\\n    if \\\"PROVISIONAL\\\" in text.upper() or \\\"WORK_READY=FALSE\\\" in text.upper():\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — provisional handoff text\\\")\\n    if not output.name.startswith(\\\"AISCORE_FIXTURES_\\\") or output.suffix.lower() != \\\".zip\\\":\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — invalid canonical ZIP filename\\\")\\n    if not note_path.name.startswith(\\\"AISCORE_FIXTURES_\\\") or note_path.suffix.lower() != \\\".txt\\\":\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — invalid canonical text filename\\\")\\n    if output.exists():\\n        raise Step0HandoffError(\\\"PACKAGE BLOCKED — output exists; no silent overwrite\\\")\\n    output.parent.mkdir(parents=True, exist_ok=True)\\n    fd, tmpname = tempfile.mkstemp(prefix=\\\".step0-validating-\\\", suffix=\\\".zip\\\", dir=output.parent)\\n    os.close(fd)\\n    try:\\n        with zipfile.ZipFile(tmpname, \\\"w\\\", compression=zipfile.ZIP_DEFLATED) as z:\\n            z.write(handoff_path, arcname=\\\"STEP0_HANDOFF.json\\\")\\n            z.write(note_path, arcname=note_path.name)\\n        with zipfile.ZipFile(tmpname) as z:\\n            if z.testzip() is not None:\\n                raise Step0HandoffError(\\\"PACKAGE BLOCKED — zip integrity error\\\")\\n        os.replace(tmpname, output)\\n    finally:\\n        if os.path.exists(tmpname):\\n            os.unlink(tmpname)\\n    return {\\n        \\\"status\\\": \\\"STEP0 WORK ZIP VALIDATED\\\",\\n        \\\"output\\\": str(output),\\n        \\\"run_id\\\": handoff[\\\"run_id\\\"],\\n        \\\"sha256\\\": hashlib.sha256(output.read_bytes()).hexdigest(),\\n        \\\"admitted\\\": len(handoff[\\\"admitted_fixtures\\\"]),\\n        \\\"required_competition_blocks_complete\\\": True,\\n    }\\n\\n\\ndef main() -> int:\\n    p = argparse.ArgumentParser()\\n    p.add_argument(\\\"--input\\\", required=True, help=\\\"STEP0_HANDOFF.json\\\")\\n    p.add_argument(\\\"--text\\\", required=True, help=\\\"AISCORE_FIXTURES_*.txt\\\")\\n    p.add_argument(\\\"--run-proof\\\", required=True, help=\\\"independent current Airtable Sweep Runs read-back\\\")\\n    p.add_argument(\\\"--output\\\", required=True, help=\\\"AISCORE_FIXTURES_*.zip\\\")\\n    args = p.parse_args()\\n    try:\\n        print(json.dumps(package(Path(args.input), Path(args.text), Path(args.run_proof), Path(args.output)), indent=2))\\n        return 0\\n    except (OSError, ValueError, KeyError, json.JSONDecodeError) as exc:\\n        print(f\\\"STEP0 WORK ZIP BLOCKED — {exc}\\\", file=sys.stderr)\\n        return 2\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    raise SystemExit(main())\\n\"}")
