def git_blob_sha(data: bytes) -> str:
    return hashlib.sha1(b"blob " + str(len(data)).encode("ascii") + b"\0" + data).hexdigest()


def self_check() -> dict:
    failures = []
    for mod, rel in MODULE_REL_PATHS.items():
        actual = git_blob_sha(MODULE_SOURCES[mod].encode("utf-8"))
        if actual != SOURCE_BLOB_SHA[rel]:
            failures.append("source blob checksum mismatch: " + rel)
    if failures:
        return {"ok": False, "errors": failures}
    _load()
    try:
        from step0_handoff_cli import validate_step0_handoff, Step0HandoffError
        from sweep_competition_scope import classify_competition
        try:
            validate_step0_handoff({"complete": False}, consumer="export")
            failures.append("provisional handoff incorrectly accepted")
        except Step0HandoffError:
            pass
        lane = classify_competition({
            "competition_name": "Bangladesh Premier League",
            "country": "Bangladesh",
            "competition_kind": "DOMESTIC_LEAGUE",
        })["lane"]
        if lane != "SCOPE_EXCLUDED":
            failures.append("Bangladesh exclusion broken")
    except Exception as exc:
        failures.append(type(exc).__name__ + ": " + str(exc))
    return {"ok": not failures, "status": "STEP0 PORTABLE SELF-CHECK PASS" if not failures else "STEP0 PORTABLE SELF-CHECK FAIL", "module_count": len(MODULE_SOURCES), "errors": failures}


def _load() -> None:
    global _loaded
    if _loaded:
        return
    for name in LOAD_ORDER:
        source = MODULE_SOURCES[name]
        obj = types.ModuleType(name)
        obj.__file__ = MODULE_REL_PATHS[name]
        sys.modules[name] = obj
        exec(compile(source, obj.__file__, "exec"), obj.__dict__)
    _loaded = True


def main() -> int:
    p = argparse.ArgumentParser(description="Self-contained Step0 validation, scope and ZIP packaging")
    sub = p.add_subparsers(dest="command", required=True)
    sub.add_parser("self-check")
    screen = sub.add_parser("scope")
    screen.add_argument("--input", required=True)
    validate = sub.add_parser("validate")
    validate.add_argument("--input", required=True)
    validate.add_argument("--consumer", choices=("export", "rank"), default="export")
    package = sub.add_parser("package")
    package.add_argument("--input", required=True)
    package.add_argument("--text", required=True)
    package.add_argument("--run-proof", required=True)
    package.add_argument("--output", required=True)
    args = p.parse_args()
    try:
        result = self_check()
        if not result["ok"]:
            raise ValueError("STEP0 PORTABLE SELF-CHECK FAIL: " + "; ".join(result["errors"]))
        if args.command == "self-check":
            print(json.dumps(result, indent=2, sort_keys=True))
            return 0
        if args.command == "scope":
            from sweep_competition_scope import screen_competitions
            raw = json.loads(Path(args.input).read_text(encoding="utf-8"))
            print(json.dumps(screen_competitions(raw["competitions"]), indent=2, sort_keys=True))
        elif args.command == "validate":
            from step0_handoff_cli import validate_step0_handoff
            handoff = json.loads(Path(args.input).read_text(encoding="utf-8"))
            print(json.dumps(validate_step0_handoff(handoff, consumer=args.consumer), indent=2, sort_keys=True))
        elif args.command == "package":
            from step0_package_cli import package as create
            result = create(Path(args.input), Path(args.text), Path(args.run_proof), Path(args.output))
            print(json.dumps(result, indent=2, sort_keys=True))
        return 0
    except (OSError, ValueError, KeyError, json.JSONDecodeError, TypeError) as exc:
        print(json.dumps({"ok": False, "status": "STEP0 PORTABLE BLOCKED", "reason": str(exc)}), file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
